<?php
namespace Tests\Feature;
use App\Models\{User,Apprentice,Programme,ProgrammeOutcome,HistoricalCohort as Cohort,HistoricalCohortRow as Row};
use App\Support\{HistoricalCohorts as H,HistoricalBenchmarks as B,ReviewedImports as Hash};
use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
use PHPUnit\Framework\Attributes\TestWith;
use Tests\TestCase;
class HistoricalBenchmarksTest extends TestCase
{
 use LazilyRefreshDatabase;
 private function f(?array $left=null,?array $right=null):array {
  $this->travelTo(now()->setDate(2026,11,16)->setTime(9,0));$admin=User::factory()->create(['role'=>'admin']);$checker=User::factory()->create(['role'=>'admin']);$historic=User::factory()->create(['role'=>'tutor','active'=>false,'name'=>'Fictional historical Tutor A']);$second=User::factory()->create(['role'=>'tutor','name'=>'Fictional historical Tutor B']);$current=User::factory()->create(['role'=>'tutor','name'=>'PRIVATE-CURRENT52']);$programme=Programme::create(['standard_code'=>'TEST52','version'=>'1.0','name'=>'Fictional matched programme52','level'=>3]);
  $left??=[['band'=>'short','n'=>5,'achieved'=>5],['band'=>'medium','n'=>10,'achieved'=>0]];$right??=[['band'=>'short','n'=>10,'achieved'=>10],['band'=>'medium','n'=>5,'achieved'=>0]];$cohorts=[];$people=[];
  foreach([$left,$right]as$period=>$spec){$year=2023+$period;$end=$year.'-06-30';$assign=[];
   foreach($spec as$part){$months=match($part['band']){'short'=>18,'medium'=>30,'long'=>42};for($i=0;$i<$part['n'];$i++){$a=Apprentice::factory()->create(['programme_id'=>$programme->id,'tutor_id'=>$current->id,'first_name'=>'PRIVATE-APPRENTICE52','start_date'=>\Carbon\Carbon::parse($end)->subMonthsNoOverflow($months)->toDateString(),'planned_end_date'=>$end]);$people[]=$a;$assign[$a->id]=$part['staff']??'A';$context=['status'=>'Completed','achievement'=>$i<$part['achieved']?'Achieved':'Not achieved','endDate'=>$year.'-06-20','achievementDate'=>$i<$part['achieved']?$year.'-07-01':null,'sourceRef'=>'PRIVATE-OUTCOME52'];if(($part['pending']??false)&&$i===0)$context=['status'=>'Active','sourceRef'=>'PRIVATE-OUTCOME52'];if(($part['late']??false)&&$i===0)$context['achievementDate']=$year.'-12-01';if(isset($part['exit'])&&$i===0)$context=['status'=>$part['exit'],'endDate'=>$year.'-06-20','sourceRef'=>'PRIVATE-OUTCOME52'];ProgrammeOutcome::factory()->create(['apprentice_id'=>$a->id,'context'=>$context]);}}
   $from=$year.'-01-01';$to=$year.'-12-31';$source=H::capture($admin,$programme->id,$from,$to,90);$c=H::create($admin,1,$programme->id,$from,$to,90,$source['source_hash'],(string)Str::uuid(),'PRIVATE-COHORT52');$sets=[];foreach(H::rows($c)as$row)$sets[$assign[$row->apprentice_id]][$row->id]=$row->version;
   foreach($sets as$key=>$selected){foreach(array_chunk($selected,25,true)as$batch){H::editBatch($admin,1,$c,$c->version,$batch,$key==='unknown'?null:($key==='A'?$historic->id:$second->id),$key==='unknown'?H::BASES[2]:H::BASES[0],'PRIVATE-ATTRIBUTION52');$c->refresh();}}H::decide($checker,1,$c,$c->version,'approve','PRIVATE-CHECKER52');$cohorts[]=$c->refresh();
  }return compact('admin','checker','historic','second','current','programme','cohorts','people');
 }
 private function report(array $f):array{return B::capture($f['admin'],$f['cohorts'][0],$f['cohorts'][1]);}
 private function url(array $f,string $suffix='',?string $hash=null):string{$q=['earlier'=>$f['cohorts'][0]->id,'later'=>$f['cohorts'][1]->id];if($hash!==null)$q['analysis']=$hash;return '/reports/historical-cohorts/same-mix'.$suffix.'?'.http_build_query($q);}
 private function reject(callable $fn):void{try{$fn();$this->fail('Expected checked refusal');}catch(ValidationException){$this->addToAssertionCount(1);}}
 public function test_same_mix_separates_composition_change_from_recorded_change():void{$f=$this->f();$r=$this->report($f);$this->assertEqualsWithDelta(100/3,$r['overall']['earlier']['raw_percentage'],.000001);$this->assertEqualsWithDelta(200/3,$r['overall']['later']['raw_percentage'],.000001);foreach(['earlier','later']as$side)$this->assertEqualsWithDelta(50,$r['overall'][$side]['same_mix_percentage'],.000001);$this->assertEquals(0,$r['overall']['same_mix_percentage_point_change']);$this->assertEquals([.5,.5,0],array_column($r['weights'],'weight'));$this->assertFalse($r['official_qar']);$this->assertFalse($r['causal_staff_effectiveness']);$this->assertFalse($r['staff_ranking']);}
 public function test_tutor_weights_and_all_band_totals_reconcile_to_the_approved_source():void{$f=$this->f();$r=$this->report($f);foreach(['earlier','later']as$i=>$side){$source=H::report($f['admin'],$f['cohorts'][$i]);$this->assertSame($source['counts'],$r['overall'][$side]['counts']);foreach($source['counts']as$key=>$n)$this->assertSame($n,array_sum(array_map(fn($band)=>$band['counts'][$key],$r['overall'][$side]['bands'])));$this->assertEquals(array_column($r['weights'],'weight'),array_column($r['groups'][0][$side]['bands'],'common_weight'));$this->assertEquals(100,$r['groups'][0][$side]['coverage_percentage']);}}
 public function test_small_positive_weight_band_withholds_without_rescaling():void{$f=$this->f([['band'=>'short','n'=>4,'achieved'=>4],['band'=>'medium','n'=>6,'achieved'=>0]],[['band'=>'short','n'=>5,'achieved'=>5],['band'=>'medium','n'=>5,'achieved'=>0]]);$r=$this->report($f);$this->assertNull($r['overall']['earlier']['same_mix_percentage']);$this->assertEqualsWithDelta(55,$r['overall']['earlier']['coverage_percentage'],.000001);$this->assertNull($r['overall']['earlier']['bands'][0]['percentage']);$this->assertFalse($r['method']['partial_coverage_rescaled']);}
 public function test_missing_band_is_not_zero_and_its_weight_is_not_dropped():void{$f=$this->f([['band'=>'short','n'=>5,'achieved'=>5]],[['band'=>'medium','n'=>5,'achieved'=>5]]);$r=$this->report($f);foreach(['earlier','later']as$side)$this->assertNull($r['overall'][$side]['same_mix_percentage']);$this->assertEquals(50,$r['overall']['earlier']['coverage_percentage']);$this->assertNull($r['overall']['same_mix_percentage_point_change']);}
 public function test_genuine_zero_and_zero_weight_unused_band_remain_distinct():void{$spec=[['band'=>'short','n'=>5,'achieved'=>0]];$r=$this->report($this->f($spec,$spec));$this->assertEquals(0,$r['overall']['earlier']['same_mix_percentage']);$this->assertEquals(100,$r['overall']['earlier']['coverage_percentage']);$this->assertEquals(0,$r['weights'][1]['weight']);}
 public function test_pending_is_not_imputed_or_ignored():void{$spec=[['band'=>'short','n'=>5,'achieved'=>5,'pending'=>true]];$r=$this->report($this->f($spec,$spec));$this->assertNull($r['overall']['earlier']['raw_percentage']);$this->assertNull($r['overall']['earlier']['same_mix_percentage']);$this->assertSame(1,$r['overall']['earlier']['bands'][0]['counts']['active']);$this->assertFalse($r['method']['missing_outcomes_imputed']);}
 public function test_after_window_outcome_stays_separate():void{$spec=[['band'=>'short','n'=>5,'achieved'=>5,'late'=>true]];$r=$this->report($this->f($spec,$spec));$this->assertSame(1,$r['overall']['earlier']['counts']['after_window']);$this->assertNull($r['overall']['earlier']['same_mix_percentage']);}
 #[TestWith(['Withdrawn'])] #[TestWith(['Transferred'])]
 public function test_withdrawn_and_transferred_stay_in_denominator(string $exit):void{$spec=[['band'=>'short','n'=>5,'achieved'=>5,'exit'=>$exit]];$r=$this->report($this->f($spec,$spec));$this->assertSame(5,$r['overall']['earlier']['counts']['mature']);$this->assertSame(4,$r['overall']['earlier']['counts']['achieved']);$this->assertEquals(80,$r['overall']['earlier']['same_mix_percentage']);}
 public function test_unknown_staff_stays_in_common_mix_but_has_no_tutor_percentage():void{$spec=[['band'=>'short','n'=>5,'achieved'=>5,'staff'=>'unknown']];$r=$this->report($this->f($spec,$spec));$this->assertSame('unknown',$r['groups'][0]['staff_key']);$this->assertNull($r['groups'][0]['earlier']['same_mix_percentage']);$this->assertEquals(100,$r['overall']['earlier']['same_mix_percentage']);$this->assertSame(10,$r['weights'][0]['members']);}
 public function test_absent_tutor_on_one_side_is_not_assumed_zero():void{$r=$this->report($this->f([['band'=>'short','n'=>5,'achieved'=>5,'staff'=>'A']],[['band'=>'short','n'=>5,'achieved'=>5,'staff'=>'B']]));$this->assertCount(2,$r['groups']);foreach($r['groups']as$g)$this->assertNull($g['same_mix_percentage_point_change']);$this->assertFalse($r['groups'][0]['later']['present']);}
 public function test_live_changes_do_not_replace_reviewed_frozen_values_or_staff_name():void{$f=$this->f();$a=$this->report($f);$f['people'][0]->update(['tutor_id'=>$f['second']->id,'start_date'=>'2020-01-01']);$f['historic']->update(['name'=>'PRIVATE-NEW-NAME52']);ProgrammeOutcome::where('apprentice_id',$f['people'][0]->id)->update(['context'=>['status'=>'Active','sourceRef'=>'Fictional later edit']]);$this->assertSame($a,$this->report($f));}
 public function test_read_only_repeat_is_deterministic():void{$f=$this->f();$events=DB::table('portal_operations_events')->count();$a=$this->report($f);$this->travel(5)->minutes();$this->assertSame($a,$this->report($f));$this->assertSame($events,DB::table('portal_operations_events')->count());$this->assertDatabaseCount('historical_cohorts',2);$this->assertDatabaseCount('historical_cohort_rows',30);}
 public function test_aggregate_does_not_export_apprentice_identity_or_private_references():void{$f=$this->f();$json=json_encode($this->report($f));foreach(['PRIVATE-APPRENTICE52','PRIVATE-CURRENT52','PRIVATE-OUTCOME52','PRIVATE-COHORT52','PRIVATE-ATTRIBUTION52','PRIVATE-CHECKER52','"apprentice_id":','"members":[' ,'"reference":']as$secret)$this->assertStringNotContainsString($secret,$json);}
 public function test_withdrawn_source_refuses_a_fresh_pinned_download():void{$f=$this->f();$r=$this->report($f);$c=$f['cohorts'][1];H::decide($f['checker'],1,$c,$c->version,'withdraw','Fictional source withdrawn52');$this->reject(fn()=>$this->report($f));$this->actingAs($f['admin'])->getJson($this->url($f,'.json',$r['analysis_hash']))->assertUnprocessable();}
 public function test_rehashed_row_change_still_fails_approval_manifest():void{$f=$this->f();$row=H::rows($f['cohorts'][0])[0];$d=$row->details;$d['attribution']['reference']='Changed evidence after approval';$row->details=$d;$row->details_hash=Hash::hash($d);$row->save();$this->reject(fn()=>$this->report($f));}
 public function test_reversed_and_identical_cohorts_are_refused():void{$f=$this->f();$this->reject(fn()=>B::capture($f['admin'],$f['cohorts'][1],$f['cohorts'][0]));$this->reject(fn()=>B::capture($f['admin'],$f['cohorts'][0],$f['cohorts'][0]));}
 #[TestWith(['tutor'])] #[TestWith(['apprentice'])] #[TestWith(['employer'])] #[TestWith(['mentor'])] #[TestWith(['manager'])] #[TestWith(['careers_adviser'])]
 public function test_other_roles_cannot_read_or_download(string $role):void{$f=$this->f();$this->actingAs(User::factory()->create(['role'=>$role]))->get($this->url($f))->assertForbidden();$this->get($this->url($f,'.json',str_repeat('0',64)))->assertForbidden();$this->get($this->url($f,'.pdf',str_repeat('0',64)))->assertForbidden();}
 public function test_private_html_and_pinned_json_match_the_report():void{$f=$this->f();$r=$this->report($f);$this->actingAs($f['admin'])->get($this->url($f))->assertOk()->assertSee('Historical comparison in context')->assertSee('50.0%')->assertSee('Download PDF')->assertHeader('Cache-Control','no-store, private')->assertHeader('Referrer-Policy','no-referrer');$this->getJson($this->url($f,'.json',$r['analysis_hash']))->assertOk()->assertJsonPath('analysis_hash',$r['analysis_hash'])->assertJsonPath('official_qar',false)->assertHeader('X-Content-Type-Options','nosniff');}
 public function test_missing_wrong_pin_and_unsupported_weights_are_refused():void{$f=$this->f();$this->actingAs($f['admin'])->getJson($this->url($f,'.json',str_repeat('0',64)))->assertStatus(409);$this->getJson($this->url($f,'.json'))->assertUnprocessable();$this->getJson($this->url($f).'&minimum=1')->assertUnprocessable();$this->getJson($this->url($f).'&weights[short]=1')->assertUnprocessable();}
 public function test_pdf_is_a_real_document_for_the_pinned_source():void{$f=$this->f();$r=$this->report($f);$response=$this->actingAs($f['admin'])->get($this->url($f,'.pdf',$r['analysis_hash']));$response->assertOk()->assertHeader('Content-Type','application/pdf')->assertHeader('Referrer-Policy','no-referrer');$this->assertStringStartsWith('%PDF',$response->getContent());if(getenv('GTA_QA_BENCHMARK52_PDF'))file_put_contents(getenv('GTA_QA_BENCHMARK52_PDF'),$response->getContent());}
 #[TestWith(['2020-02-29','2022-02-28','up_to_24'])] #[TestWith(['2020-02-29','2022-03-01','over_24_to_36'])] #[TestWith(['2020-02-29','2023-02-28','over_24_to_36'])] #[TestWith(['2020-02-29','2023-03-01','over_36'])]
 public function test_band_uses_calendar_anniversaries(string $a,string $b,string $expected):void{$this->assertSame($expected,B::band($a,$b));}
