 public function test_invalid_dates_are_not_silently_classified(string $a,string $b):void{$this->reject(fn()=>B::band($a,$b));}
 public function test_ceo_can_use_the_same_management_report_without_changing_attributions():void{$f=$this->f();$this->actingAs(User::factory()->create(['role'=>'ceo']))->get($this->url($f))->assertOk()->assertSee('Fictional historical Tutor A');$this->assertFalse($f['historic']->fresh()->active);}
 public function test_draft_or_damaged_cohort_cannot_be_used_for_a_context_report():void{$f=$this->f();DB::table('historical_cohorts')->where('id',$f['cohorts'][0]->id)->update(['state'=>'Draft']);$this->reject(fn()=>$this->report($f));}
 public function test_release_is_read_only_and_not_target_acceptance():void{$r=\App\Support\Release52Check::report();$this->assertSame('52',$r['pack']);$this->assertNotSame('needs_attention',$r['status']);$this->assertFalse($r['actual_target_acceptance']);$this->assertSame(0,$r['new_migrations']);$this->artisan('gta:release-check52')->assertSuccessful();$this->assertDatabaseCount('historical_cohorts',0);}
